1	//! Streaming helpers for the tarball path.
2	//!
3	//! Four flows live here:
4	//!
5	//! * [`verify_file`] hashes a cache hit before it can be served.
6	//! * [`download_verified_to_cache`] hashes an upstream response into a
7	//!   temp file and promotes it only after the declared SRI matches.
8	//! * [`download_verified_to_temp`] hashes an upstream response into a
9	//!   temp file for mirror-less pass-through.
10	//! * [`stream_file`] yields an already verified file to the response.
11	
12	use crate::storage::TarballWrite;
13	use axum::body::{Body, Bytes};
14	use futures_util::{StreamExt, stream};
15	use ssri::{Integrity, IntegrityChecker};
16	use std::{
17	    io::{self, SeekFrom},
18	    path::PathBuf,
19	};
20	use tokio::{
21	    fs::File,
22	    io::{AsyncReadExt, AsyncSeekExt},
23	};
24	
25	/// Chunk size for reading from a cached file. 64 KiB keeps syscall
26	/// overhead low without buffering a meaningful fraction of a
27	/// multi-MB tarball.
28	const READ_CHUNK: usize = 64 * 1024;
29	
30	pub fn parse_integrity(value: &str) -> Result<Integrity, ssri::Error> {
31	    let integrity: Integrity = value.parse()?;
32	    ensure_supported_hash(&integrity)?;
33	    Ok(integrity)
34	}
35	
36	fn ensure_supported_hash(integrity: &Integrity) -> Result<(), ssri::Error> {
37	    if integrity.hashes.is_empty() {
38	        return Err(ssri::Error::ParseIntegrityError(
39	            "integrity string contains no supported hashes".to_string(),
40	        ));
41	    }
42	    Ok(())
43	}
44	
45	pub fn integrity_checker(integrity: &Integrity) -> Result<IntegrityChecker, ssri::Error> {
46	    ensure_supported_hash(integrity)?;
47	    Ok(IntegrityChecker::new(integrity.clone()))
48	}
49	
50	#[derive(Debug)]
51	pub enum TarballStreamError {
52	    Upstream { url: String, source: reqwest::Error },
53	    Io(io::Error),
54	    Integrity(ssri::Error),
55	    TooLarge { limit: u64, received: u64 },
56	}
57	
58	/// Hash a cached file against `integrity`, then rewind the same open
59	/// file so the caller can stream the exact bytes that were checked.
60	pub async fn verify_file(
61	    mut file: File,
62	    integrity: &Integrity,
63	) -> Result<File, TarballStreamError> {
64	    let mut checker = integrity_checker(integrity).map_err(TarballStreamError::Integrity)?;
65	    let mut buf = vec![0u8; READ_CHUNK];
66	    loop {
67	        let bytes_read = file.read(&mut buf).await.map_err(TarballStreamError::Io)?;
68	        if bytes_read == 0 {
69	            break;
70	        }
71	        checker.input(&buf[..bytes_read]);
72	    }
73	    checker.result().map_err(TarballStreamError::Integrity)?;
74	    file.seek(SeekFrom::Start(0)).await.map_err(TarballStreamError::Io)?;
75	    Ok(file)
76	}
77	
78	/// Download an upstream response into `write`, verify the complete body,
79	/// and atomically promote it to the cache. No bytes become cache-visible
80	/// until the declared SRI matches.
81	pub async fn download_verified_to_cache(
82	    response: reqwest::Response,
83	    mut write: TarballWrite,
84	    integrity: &Integrity,
85	    max_bytes: u64,
86	) -> Result<u64, TarballStreamError> {
87	    let len = match download_verified(response, &mut write, integrity, max_bytes).await {
88	        Ok(len) => len,
89	        Err(err) => {
90	            write.abandon().await;
91	            return Err(err);
92	        }
93	    };
94	    write.finalize().await.map_err(TarballStreamError::Io)?;
95	    Ok(len)
96	}
97	
98	pub async fn download_verified_to_temp(
99	    response: reqwest::Response,
100	    mut write: TarballWrite,
101	    integrity: &Integrity,
102	    max_bytes: u64,
103	) -> Result<(File, u64, PathBuf), TarballStreamError> {
104	    if let Err(err) = download_verified(response, &mut write, integrity, max_bytes).await {
105	        write.abandon().await;
106	        return Err(err);
107	    }
108	    write.into_temp_file().await.map_err(TarballStreamError::Io)
109	}
110	
111	async fn download_verified(
112	    response: reqwest::Response,
113	    write: &mut TarballWrite,
114	    integrity: &Integrity,
115	    max_bytes: u64,
116	) -> Result<u64, TarballStreamError> {
117	    let url = response.url().to_string();
118	    if let Some(received) = response.content_length()
119	        && received > max_bytes
120	    {
121	        return Err(TarballStreamError::TooLarge { limit: max_bytes, received });
122	    }
123	    let mut upstream = response.bytes_stream();
124	    let mut checker = integrity_checker(integrity).map_err(TarballStreamError::Integrity)?;
125	    let mut written = 0u64;
126	    while let Some(chunk_result) = upstream.next().await {
127	        let chunk = match chunk_result {
128	            Ok(chunk) => chunk,
129	            Err(source) => return Err(TarballStreamError::Upstream { url, source }),
130	        };
131	        let received = written.saturating_add(chunk.len() as u64);
132	        if received > max_bytes {
133	            return Err(TarballStreamError::TooLarge { limit: max_bytes, received });
134	        }
135	        if let Err(err) = write.write_all(&chunk).await {
136	            return Err(TarballStreamError::Io(err));
137	        }
138	        checker.input(&chunk);
139	        written = received;
140	    }
141	
142	    if let Err(err) = checker.result() {
143	        return Err(TarballStreamError::Integrity(err));
144	    }
145	    Ok(written)
146	}
