78	impl TarballWrite {
79	    pub async fn write_all(&mut self, bytes: &[u8]) -> std::io::Result<()> {
80	        match self.file.as_mut() {
81	            Some(file) => file.write_all(bytes).await,
82	            None => Err(std::io::Error::other("tarball cache writer is closed")),
83	        }
84	    }
