/// The live state a [`stream_verified_to_cache`] body carries across its
/// stream steps: the upstream chunk source, the still-open cache temp
/// writer, the running SRI hasher, and the byte budget. Holding `write`
/// here is what arms mid-stream cleanup — if the body is dropped before
/// end-of-stream (client disconnect), this state drops, and
/// [`TarballWrite`]'s `Drop` removes the temp file.
struct TeeState {
    upstream: BoxStream<'static, reqwest::Result<Bytes>>,
    write: Option<TarballWrite>,
    checker: IntegrityChecker,
    written: u64,
    max_bytes: u64,
}

impl TeeState {
    /// Drop the temp file without promoting it. Used on every terminal
    /// path except a clean SRI match: an SRI mismatch, an upstream error,
    /// a write failure, or an over-budget stream all leave the cache
    /// untouched.
    async fn abandon(&mut self) {
        if let Some(write) = self.write.take() {
            write.abandon().await;
        }
    }
}

